ConvexCone.mem_mk.{u_1, u_2} {𝕜 : Type u_1} {E : Type u_2} [OrderedSemiring 𝕜] [AddCommMonoid E] [SMul 𝕜 E] {s : Set E}
  {h₁ : ∀ ⦃c : 𝕜⦄, 0 < c → ∀ ⦃x : E⦄, x ∈ s → c • x ∈ s} {h₂ : ∀ ⦃x : E⦄, x ∈ s → ∀ ⦃y : E⦄, y ∈ s → x + y ∈ s}
  {x : E} : x ∈ { carrier := s, smul_mem' := h₁, add_mem' := h₂ } ↔ x ∈ s
